const base = process.env.PUBLIC_URL || "";

function shuffle(list) {
  const arr = [...list];
  for (let i = arr.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

export async function getVisualize(valueFilter, numFilter, subType) {
  const vf = String(valueFilter).toLowerCase();
  const n = String(numFilter);
  const st = String(subType).toLowerCase();
  const url = `${base}/data/visualize/visualize_${vf}_${n}_${st}.json`;
  const res = await fetch(url);
  if (!res.ok) {
    throw new Error(`Failed to load ${url}`);
  }
  return res.json();
}

export async function getExamples(valueFilter, numFilter, count = 12) {
  const vf = String(valueFilter).toLowerCase();
  const n = String(numFilter);
  const url = `${base}/data/examples/examples_${vf}_${n}.json`;
  const res = await fetch(url);
  if (!res.ok) {
    throw new Error(`Failed to load ${url}`);
  }
  const pool = await res.json();
  return shuffle(pool).slice(0, Math.min(count, pool.length));
}
